-- Orbital Phase 2: apply once after 20260814_orbital_foundation.sql.
create table if not exists public.artifacts (id uuid primary key default gen_random_uuid(), workspace_id uuid not null references public.workspaces(id) on delete cascade, name text not null, mime_type text not null, storage_key text not null unique, content_hash text not null, status text not null default 'uploaded' check(status in ('uploaded','normalized','failed')), normalized_artifact_id uuid references public.artifacts(id) on delete set null, failure_reason text, created_by uuid not null references auth.users(id), created_at timestamptz not null default now());
create table if not exists public.knowledge_collections (id uuid primary key default gen_random_uuid(), workspace_id uuid not null references public.workspaces(id) on delete cascade, name text not null, created_by uuid not null references auth.users(id), created_at timestamptz not null default now(), unique(workspace_id,name));
create table if not exists public.collection_artifacts (collection_id uuid not null references public.knowledge_collections(id) on delete cascade, artifact_id uuid not null references public.artifacts(id) on delete cascade, primary key(collection_id,artifact_id));
create table if not exists public.knowledge_chunks (id uuid primary key default gen_random_uuid(), artifact_id uuid not null references public.artifacts(id) on delete cascade, ordinal integer not null, content text not null, start_offset integer not null, end_offset integer not null, unique(artifact_id,ordinal));
create table if not exists public.research_reports (id uuid primary key default gen_random_uuid(), workspace_id uuid not null references public.workspaces(id) on delete cascade, title text not null, content text not null, citations jsonb not null default '[]'::jsonb, artifact_id uuid references public.artifacts(id), created_by uuid not null references auth.users(id), created_at timestamptz not null default now());
create table if not exists public.adapter_registrations (id uuid primary key default gen_random_uuid(), workspace_id uuid not null references public.workspaces(id) on delete cascade, name text not null check(name in ('graphify','graft','headroom','agent_reach')), manifest jsonb not null, enabled boolean not null default false, created_by uuid not null references auth.users(id), created_at timestamptz not null default now(), unique(workspace_id,name));
create table if not exists public.skill_observations (id uuid primary key default gen_random_uuid(), workspace_id uuid not null references public.workspaces(id) on delete cascade, title text not null, manifest jsonb not null, provenance jsonb not null default '{}'::jsonb, status text not null default 'draft' check(status in ('draft','dismissed','accepted')), created_by uuid not null references auth.users(id), created_at timestamptz not null default now());
